import { useState } from 'react';
import { JxTagInput, JxChip, JxDivider } from '@jinx-ui/react';

export interface ArticleTagPickerProps {
  label?: string;
  defaultTags?: string[];
  placeholder?: string;
  onChange?: (tags: string[]) => void;
}

export default function ArticleTagPicker({
  label = 'Теги статьи',
  defaultTags = [],
  placeholder = 'Введите тег и нажмите Enter',
  onChange,
}: ArticleTagPickerProps) {
  const [tags, setTags] = useState<string[]>(defaultTags);

  const update = (next: string[]) => {
    setTags(next);
    onChange?.(next);
  };

  const remove = (tag: string) => {
    update(tags.filter((item) => item !== tag));
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <label className="jx-label" htmlFor="article-tags">
        {label}
      </label>

      <JxTagInput
        ariaLabel={label}
        placeholder={placeholder}
        value={tags}
        onValueChange={update}
      />

      <JxDivider label={`Выбрано: ${tags.length}`} />

      {tags.length > 0 ? (
        <div
          role="list"
          aria-label="Выбранные теги"
          style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}
        >
          {tags.map((tag) => (
            <JxChip
              key={tag}
              role="listitem"
              active
              removable
              onRemove={() => remove(tag)}
            >
              {tag}
            </JxChip>
          ))}
        </div>
      ) : (
        <span
          style={{
            color: 'var(--jx-text-3)',
            fontFamily: 'var(--jx-font-sans)',
            fontSize: '13px',
          }}
        >
          Пока ни одного тега
        </span>
      )}
    </div>
  );
}

